    if (['<>', '!=', '<=', '>=', '||'].includes(two)) { toks.push({ t: 'op', v: two === '!=' ? '<>' : two }); i += 2; continue; }
    if ('=<>+-*/%(),.?;'.includes(ch)) { toks.push({ t: ch === '?' ? 'param' : 'op', v: ch === '?' ? null : ch }); i++; continue; }
