  const eatOp = (v) => { if (isOp(v)) { p++; return true; } return false; };
  const needKw = (v) => { if (!eatKw(v)) fail('syntax', `expected ${v} near ${show()}`); };
  const needOp = (v) => { if (!eatOp(v)) fail('syntax', `expected ${v} near ${show()}`); };
